styles:
html, body {
  height: 100%;
  width: 100%;
  margin: 0;
  overflow: hidden;
  font-family: 'Google Sans', Roboto, Arial, sans-serif;
}
body {
  background-color: #272930;
  color: #ADAFB8;
  border-radius: 16px;
}
.chart-container-wrapper {
  display: flex;
  flex-direction: column;
  height: 100%;
  width: 100%;
  box-sizing: border-box;
}
.chart-header {
  white-space: pre-wrap;
  word-break: break-word;
  display: none;
  padding: 16px 16px 0 16px;
  flex-shrink: 0;
  font-size: 16px;
  font-weight: bold;
  color: #E8E8E8;
  font-family: 'Google Sans', Roboto, Arial, sans-serif;
}
#chart-container {

  flex-grow: 1;
  min-height: 0;

  position: relative;
  padding: 8px 16px 16px 16px;
  box-sizing: border-box;
}
canvas {
  width: 100% !important;
  height: 100% !important;
}
